const body = $input.first().json.body || {};
const value = body.entry?.[0]?.changes?.[0]?.value;
const messages = value?.messages;
if (!messages || !messages[0]) return [];
const msg = messages[0];
let from = msg.from, messageId = msg.id, rawText = '', question = '';
if (msg.type === 'text') rawText = (msg.text?.body || '').trim();
else if (msg.type === 'interactive' && msg.interactive?.type === 'button_reply') {
  rawText = msg.interactive.button_reply.id;
  question = rawText;
}
if (!rawText) return [];
const PASSWORD = '6778';
let authenticated = false;
if (rawText === PASSWORD) { authenticated = true; question = '__HELP__'; }
else if (rawText.startsWith(PASSWORD + ' ')) { authenticated = true; question = rawText.slice(PASSWORD.length + 1).trim(); }
else { authenticated = false; question = rawText; }
return [{ json: { from, messageId, rawText, question, authenticated } }];

const question = $("Extract Message").first().json.question;
const today = new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Hong_Kong" });
const sp = `You are a SQL expert for GO24 Fitness gym chain in Hong Kong. Generate ONE PostgreSQL SELECT query. Return ONLY raw SQL, no markdown, no explanation.

Today HKT: ${today}

pgm.members(member_code,name,phone,email,gender,dob DATE,join_date DATE,plan_type,plan_start DATE,plan_end DATE,status VARCHAR,pt_sessions_left INT,last_visit DATE,total_paid NUMERIC,branch,notes) status:Active,Frozen,Expired,Cancelled
commissions.sold(club,sell_date DATE,user_number,first_name,product_name,net_sold NUMERIC,gross_sold NUMERIC,is_new BOOL,sold_employee,commission_category)
commissions.done(club,done_date DATE,user_number,product_name,done_amount NUMERIC,done_employee,department,commission_category)
studio.classes(club,class_name,category,employee_name,start_date DATE,day_of_week,class_time,users_limit INT,users_assigned INT,users_present INT,rating NUMERIC)
studio.by_member(club,class_date DATE,class_name,first_name,last_name,user_number,has_presence BOOL)
pos.transactions(club,transaction_date DATE,product_name,category,quantity NUMERIC,net_amount NUMERIC,gross_amount NUMERIC,payment_method,full_name,employee)
payments.epayment_log(club,user_number,name,payment_date DATE,amount NUMERIC,net_amount NUMERIC,status,provider,membership_status,payment_plan)
Rules: LIMIT 20 detail queries; no limit aggregations; name ILIKE; readable English aliases`;
return [{ json: { geminiBody: JSON.stringify({ systemInstruction: { parts: [{ text: sp }] }, contents: [{ role: "user", parts: [{ text: question }] }], generationConfig: { maxOutputTokens: 600, temperature: 0.1 } }), question } }];

const r = $input.first().json;
let sql = r.candidates?.[0]?.content?.parts?.[0]?.text || "";
sql = sql.replace(/```sql/gi, "").replace(/```/g, "").trim();
if (!sql.toUpperCase().startsWith("SELECT")) throw new Error("Non-SELECT: " + sql.slice(0, 100));
return [{ json: { sql, question: $("Build SQL Request").first().json.question } }];

const results = $input.all().map(i => i.json);
const question = $("Extract SQL").first().json.question;
const sp2 = "You are a helpful assistant for GO24 Fitness in Hong Kong. Reply in the same language as the question (Cantonese or English). Be brief (1-4 sentences). Use numbers clearly. Add 1-2 relevant emoji. Do NOT mention SQL or database.";
const userContent = `Question: ${question}\n\nData (${results.length} rows):\n${JSON.stringify(results, null, 2)}`;
return [{ json: { geminiBody: JSON.stringify({ systemInstruction: { parts: [{ text: sp2 }] }, contents: [{ role: "user", parts: [{ text: userContent }] }], generationConfig: { maxOutputTokens: 400, temperature: 0.7 } }) } }];

const r = $input.first().json;
const answer = r.candidates?.[0]?.content?.parts?.[0]?.text || "唔好意思，暫時無法回答。";
return [{ json: { answer, to: $("Extract Message").first().json.from } }];

